sp_widget.client_script:
api.controller = function($scope, $window, $timeout) {
    var c = this;

    c.sidebarCollapsed = false;
    c.searchText = '';
    c.loading = false;
    c.showNotificationsPopover = false;
    c.activeNotifTab = 'all';

    c.toggleNotifications = function($event) {
        if ($event) $event.stopPropagation();
        c.showNotificationsPopover = !c.showNotificationsPopover;
    };

    c.dismissNotif = function(index) {
        if (c.data.notifications && c.data.notifications.length > index) {
            c.data.notifications.splice(index, 1);
            c.data.unreadCount = c.data.notifications.length;
        }
    };

    c.clearAllNotifications = function() {
        c.data.notifications = [];
        c.data.unreadCount = 0;
    };

    c.getFilteredNotifications = function() {
        if (!c.data || !c.data.notifications) return [];
        if (c.activeNotifTab === 'risk') {
            return c.data.notifications.filter(function(n) { return n.type === 'risk'; });
        }
        if (c.activeNotifTab === 'opportunities') {
            return c.data.notifications.filter(function(n) { return n.type === 'opportunity'; });
        }
        if (c.activeNotifTab === 'interviews') {
            return c.data.notifications.filter(function(n) { return n.type === 'interview'; });
        }
        return c.data.notifications;
    };

    c.toggleSidebar = function() {
        c.sidebarCollapsed = !c.sidebarCollapsed;
    };

    c.refresh = function() {
        c.loading = true;
        c.server.refresh().then(function() {
            c.loading = false;
        });
    };


    c.goTo = function(pageId) {
        if (!pageId) return;
        var map = {
            'dashboard': 'campus360_tpo_home',
            'home': 'campus360_tpo_home',
            'campus360_tpo_home': 'campus360_tpo_home',
            'students': 'campus360_tpo_student_management',
            'student_management': 'campus360_tpo_student_management',
            'campus360_tpo_student_management': 'campus360_tpo_student_management',
            'skills': 'campus360_tpo_skill_intelligence_new',
            'skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence_new': 'campus360_tpo_skill_intelligence_new',
            'assessments': 'student_assessments_new',
            'student_assessments': 'student_assessments_new',
            'student_assessments_new': 'student_assessments_new',
            'companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies_new': 'campus360_tpo_companies_new',
            'opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities_new': 'campus360_tpo_opportunities_new',
            'applications': 'campus360_tpo_application_new',
            'application': 'campus360_tpo_application_new',
            'campus360_tpo_application': 'campus360_tpo_application_new',
            'campus360_tpo_application_new': 'campus360_tpo_application_new',
            'interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews_new': 'campus360_tpo_interviews_new',
            'outcomes': 'campus360_tpo_placement_outcomes',
            'placement_outcomes': 'campus360_tpo_placement_outcomes',
            'campus360_tpo_placement_outcomes': 'campus360_tpo_placement_outcomes',
            'training': 'campus360_tpo_training_programs',
            'training_programs': 'campus360_tpo_training_programs',
            'campus360_tpo_training_programs': 'campus360_tpo_training_programs',
            'enrollments': 'campus360_tpo_training_programs',
            'campus360_tpo_enrollments': 'campus360_tpo_training_programs',
            'mock_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_mock_interviews': 'campus360_tpo_interviews_new',
            'risk': 'campus360_tpo_student_management',
            'campus360_tpo_risk_intelligence': 'campus360_tpo_student_management',
            'interventions': 'campus360_tpo_student_management',
            'campus360_tpo_interventions': 'campus360_tpo_student_management',
            'readiness': 'campus360_tpo_skill_intelligence_new',
            'ai_assistant': 'campus360_tpo_ai_assistant',
            'campus360_tpo_ai_assistant': 'campus360_tpo_ai_assistant'
        };
        var target = map[pageId] || pageId;
        if (typeof $window !== 'undefined' && $window.location) {
            $window.location.href = '?id=' + encodeURIComponent(target);
        } else {
            window.location.href = '?id=' + encodeURIComponent(target);
        }
    };
    c.goToPage = function(pageId) { c.goTo(pageId); };
    c.navigate = function(pageId) { c.goTo(pageId); };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 TPO DASHBOARD
   FULL-WIDTH SERVICE PORTAL FIX
   ========================================================= */


/* =========================================================
   GLOBAL RESET
   ========================================================= */

html,
body {

    width: 100% !important;

    min-width: 100% !important;

    height: 100% !important;

    margin: 0 !important;

    padding: 0 !important;

    overflow: hidden !important;
}


/* =========================================================
   IMPORTANT SERVICE PORTAL FIX

   DO NOT USE:

       left: 50%
       margin-left: -50vw

   Those caused the large blank space / horizontal scroll.

   Instead Campus360 is positioned against the viewport.
   ========================================================= */

.c360-app {

    position: fixed !important;

    z-index: 9999 !important;

    top: 0 !important;

    right: 0 !important;

    bottom: 0 !important;

    left: 0 !important;

    width: 100vw !important;

    height: 100vh !important;

    min-width: 0 !important;

    max-width: none !important;

    min-height: 0 !important;

    margin: 0 !important;

    padding: 0 !important;

    overflow: hidden !important;

    box-sizing: border-box !important;

    background: #f6f8fb;

    color: #172033;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Roboto,
        Helvetica,
        Arial,
        sans-serif;

    line-height: 1.45;
}


/* Everything inside uses border-box */

.c360-app *,
.c360-app *::before,
.c360-app *::after {

    box-sizing: border-box;
}


/* =========================================================
   HIDE SERVICE PORTAL NAVIGATION

   These are the Knowledge / Catalog / Requests /
   System Status / Cart / Tours / System Administrator
   items seen in your screenshot.

   The Campus360 fixed application covers the portal
   underneath the ServiceNow Designer toolbar.
   ========================================================= */

body:has(.c360-app) .sp-navbar,
body:has(.c360-app) .sp-navbar-wrapper,
body:has(.c360-app) .sp-header,
body:has(.c360-app) .portal-navbar,
body:has(.c360-app) .portal-header,
body:has(.c360-app) .sp-nav,
body:has(.c360-app) .sp-nav-bar,
body:has(.c360-app) .header-nav,
body:has(.c360-app) nav.navbar,
body:has(.c360-app) .navbar.navbar-default,
body:has(.c360-app) .navbar.navbar-inverse {

    display: none !important;
}


/* =========================================================
   COLORS
   ========================================================= */

:root {

    --c360-purple: #7c3aed;

    --c360-purple-dark: #5b21b6;

    --c360-purple-light: #f3e8ff;

    --c360-blue: #3b82f6;

    --c360-blue-light: #eff6ff;

    --c360-green: #10b981;

    --c360-green-light: #ecfdf5;

    --c360-red: #ef3f63;

    --c360-red-light: #fff1f2;

    --c360-yellow: #f5b91b;

    --c360-yellow-light: #fffbea;

    --c360-orange: #f97316;

    --c360-orange-light: #fff7ed;

    --c360-violet: #8b5cf6;

    --c360-violet-light: #f5f3ff;

    --c360-dark: #111025;

    --c360-dark-2: #18142f;

    --c360-text: #172033;

    --c360-muted: #728096;

    --c360-border: #e4e8ef;

    --c360-background: #f6f8fb;

    --c360-white: #ffffff;

    --c360-shadow:
        0 8px 30px rgba(26,31,54,0.055);

    --c360-shadow-hover:
        0 14px 36px rgba(26,31,54,0.11);

    --c360-radius: 18px;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.c360-sidebar {

    position: absolute !important;

    top: 0;

    left: 0;

    bottom: 0;

    z-index: 20;

    width: 275px;

    height: 100%;

    display: flex;

    flex-direction: column;

    overflow: hidden;

    background:
        linear-gradient(
            180deg,
            #111025 0%,
            #100e22 100%
        );

    color: #ffffff;

    border-right:
        1px solid rgba(255,255,255,0.04);

    transition:
        width 0.25s ease;
}


/* =========================================================
   MAIN

   This starts EXACTLY after the 275px sidebar.

   No extra left spacing.
   No centered container.
   No horizontal overflow.
   ========================================================= */

.c360-main {

    position: absolute !important;

    top: 0;

    right: 0;

    bottom: 0;

    left: 275px;

    width: auto !important;

    height: 100%;

    min-width: 0 !important;

    max-width: none !important;

    margin: 0 !important;

    padding: 0 !important;

    overflow-y: auto;

    overflow-x: hidden;

    background: var(--c360-background);

    transition:
        left 0.25s ease;
}


/* =========================================================
   BRAND
   ========================================================= */

.c360-brand {

    height: 84px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    padding: 18px 20px;

    border-bottom:
        1px solid rgba(255,255,255,0.04);
}

.c360-brand-logo {

    width: 44px;

    height: 44px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 13px;

    background:
        linear-gradient(
            135deg,
            #8b5cf6,
            #6d28d9
        );

    color: #ffffff;

    font-size: 25px;

    font-weight: 800;

    box-shadow:
        0 8px 20px rgba(124,58,237,0.3);
}

.c360-brand-text {

    margin-left: 13px;
}

.c360-brand-name {

    color: #ffffff;

    font-size: 19px;

    line-height: 1.1;

    font-weight: 800;

    letter-spacing: -0.4px;
}

.c360-brand-subtitle {

    margin-top: 4px;

    color: #a78bfa;

    font-size: 10px;

    font-weight: 700;

    letter-spacing: 0.7px;
}


/* =========================================================
   TPO PROFILE
   ========================================================= */

.c360-tpo-profile {

    flex-shrink: 0;

    margin: 16px 18px 12px;

    padding: 13px 12px;

    display: flex;

    align-items: center;

    border-radius: 15px;

    background:
        linear-gradient(
            135deg,
            rgba(124,58,237,0.16),
            rgba(88,28,135,0.12)
        );

    border:
        1px solid rgba(124,58,237,0.22);
}

.c360-tpo-avatar {

    width: 40px;

    height: 40px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background:
        linear-gradient(
            135deg,
            #8b5cf6,
            #6d28d9
        );

    color: #ffffff;

    font-weight: 800;

    box-shadow:
        0 5px 15px rgba(124,58,237,0.28);
}

.c360-tpo-info {

    min-width: 0;

    margin-left: 11px;
}

.c360-tpo-name {

    color: #ffffff;

    font-size: 13px;

    font-weight: 700;
}

.c360-tpo-role {

    margin-top: 2px;

    color: #b9b5cf;

    font-size: 10px;
}


/* =========================================================
   SIDEBAR NAV
   ========================================================= */

.c360-sidebar-nav {

    flex: 1;

    min-height: 0;

    padding: 5px 13px 15px;

    overflow-y: auto;

    overflow-x: hidden;
}

.c360-sidebar-nav::-webkit-scrollbar {

    width: 4px;
}

.c360-sidebar-nav::-webkit-scrollbar-thumb {

    background:
        rgba(255,255,255,0.15);

    border-radius: 10px;
}

.c360-nav-title {

    margin: 16px 12px 7px;

    color: #9995b0;

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 0.65px;
}

.c360-nav-item {

    min-height: 40px;

    margin: 3px 0;

    padding: 0 12px;

    display: flex;

    align-items: center;

    color: #d9d6e6;

    border-radius: 11px;

    font-size: 13px;

    font-weight: 500;

    transition:
        background 0.2s ease,
        color 0.2s ease,
        transform 0.2s ease;
}

.c360-nav-item i {

    width: 20px;

    flex-shrink: 0;

    margin-right: 10px;

    color: #aaa6bd;

    text-align: center;

    font-size: 14px;
}

.c360-nav-item span:not(.c360-nav-count) {

    flex: 1;
}

.c360-nav-item:hover {

    color: #ffffff;

    background:
        rgba(255,255,255,0.07);

    transform: translateX(2px);

    text-decoration: none;
}

.c360-nav-item:hover i {

    color: #ffffff;
}

.c360-nav-item.active {

    color: #ffffff;

    background:
        linear-gradient(
            90deg,
            #7c3aed,
            #8338ec
        );

    box-shadow:
        0 7px 18px rgba(124,58,237,0.25);
}

.c360-nav-item.active i {

    color: #ffffff;
}

.c360-nav-count {

    min-width: 24px;

    height: 22px;

    padding: 0 7px;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    border-radius: 20px;

    font-size: 10px;

    font-weight: 800;
}

.c360-nav-count.purple {

    color: #d8b4fe;

    background:
        rgba(124,58,237,0.34);
}

.c360-nav-count.blue {

    color: #93c5fd;

    background:
        rgba(59,130,246,0.20);
}

.c360-nav-count.orange {

    color: #fdba74;

    background:
        rgba(249,115,22,0.20);
}

.c360-nav-count.green {

    color: #6ee7b7;

    background:
        rgba(16,185,129,0.18);
}

.c360-nav-count.red {

    color: #fda4af;

    background:
        rgba(239,63,99,0.22);
}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.c360-sidebar-footer {

    flex-shrink: 0;

    padding: 14px 10px 17px;

    color: #8c889e;

    border-top:
        1px solid rgba(255,255,255,0.04);

    font-family: monospace;

    font-size: 9px;

    text-align: center;
}


/* =========================================================
   TOP BAR
   ========================================================= */

.c360-topbar {

    position: sticky;

    top: 0;

    z-index: 100;

    width: 100%;

    height: 69px;

    flex-shrink: 0;

    padding: 0 25px;

    display: flex;

    align-items: center;

    background:
        rgba(255,255,255,0.98);

    border-bottom:
        1px solid var(--c360-border);

    backdrop-filter: blur(12px);
}

.c360-breadcrumb {

    flex-shrink: 0;

    display: flex;

    align-items: center;

    white-space: nowrap;

    color: #637085;

    font-size: 13px;
}

.c360-breadcrumb i {

    margin: 0 10px;

    color: #b1bac8;
}

.c360-breadcrumb strong {

    color: #121827;
}


/* =========================================================
   SEARCH
   ========================================================= */

.c360-search {

    width: min(42vw, 485px);

    height: 38px;

    margin-left: 26px;

    display: flex;

    align-items: center;

    padding: 0 13px;

    border:
        1px solid #dfe4ec;

    border-radius: 12px;

    background: #f8fafc;
}

.c360-search:focus-within {

    border-color: #a78bfa;

    background: #ffffff;

    box-shadow:
        0 0 0 3px rgba(124,58,237,0.08);
}

.c360-search i {

    margin-right: 11px;

    color: #8a96a8;

    font-size: 14px;
}

.c360-search input {

    width: 100%;

    height: 100%;

    padding: 0;

    outline: none;

    border: 0;

    background: transparent;

    color: #202938;

    font-size: 12px;
}

.c360-search input::placeholder {

    color: #8b96a8;
}


/* =========================================================
   TOP ACTIONS
   ========================================================= */

.c360-top-actions {

    position: relative;

    margin-left: auto;

    display: flex;

    align-items: center;
}

.c360-icon-button {

    position: relative;

    width: 39px;

    height: 39px;

    margin-left: 9px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid #dfe4ec;

    border-radius: 11px;

    background: #ffffff;

    color: #526075;

    font-size: 14px;
}

.c360-icon-button:hover {

    color: var(--c360-purple);

    border-color: #c4b5fd;

    background: #faf7ff;
}

.notification-dot {

    position: absolute;

    top: 7px;

    right: 7px;

    width: 7px;

    height: 7px;

    border:
        1.5px solid #ffffff;

    border-radius: 50%;

    background: #ef3f63;
}

.c360-top-divider {

    width: 1px;

    height: 33px;

    margin: 0 12px;

    background: #e5e8ee;
}

.c360-user-profile {

    display: flex;

    align-items: center;
}

.c360-user-avatar {

    width: 35px;

    height: 35px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background:
        linear-gradient(
            135deg,
            #8b5cf6,
            #6d28d9
        );

    color: #ffffff;

    font-size: 11px;

    font-weight: 800;
}

.c360-user-details {

    margin-left: 9px;

    display: flex;

    flex-direction: column;
}

.c360-user-details strong {

    color: #172033;

    font-size: 12px;
}

.c360-user-details span {

    margin-top: 1px;

    color: #98a2b1;

    font-size: 10px;
}


/* =========================================================
   NOTIFICATIONS
   ========================================================= */

.c360-notification-popover {

    position: absolute;

    z-index: 2000;

    top: 53px;

    right: 45px;

    width: 410px;

    max-height: 580px;

    overflow: hidden;

    background: #ffffff;

    border:
        1px solid #e2e6ed;

    border-radius: 16px;

    box-shadow:
        0 18px 50px rgba(21,24,44,0.17);
}

.notification-header {

    padding: 17px 18px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    border-bottom:
        1px solid #edf0f4;
}

.notification-header strong {

    display: block;

    color: #161c2b;

    font-size: 13px;
}

.notification-header span {

    display: block;

    margin-top: 3px;

    color: #8a95a7;

    font-size: 10px;
}

.notification-header button {

    border: 0;

    background: transparent;

    color: var(--c360-purple);

    font-size: 11px;

    font-weight: 700;
}

.notification-tabs {

    padding: 9px 12px;

    display: flex;

    gap: 5px;

    border-bottom:
        1px solid #edf0f4;
}

.notification-tabs button {

    padding: 7px 11px;

    border: 0;

    border-radius: 8px;

    background: transparent;

    color: #758196;

    font-size: 10px;

    font-weight: 700;
}

.notification-tabs button.active {

    background: #f2eafe;

    color: #6d28d9;
}

.notification-list {

    max-height: 440px;

    overflow-y: auto;
}

.notification-item {

    position: relative;

    padding: 13px 15px;

    display: flex;

    border-bottom:
        1px solid #f0f2f5;
}

.notification-icon {

    width: 33px;

    height: 33px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;
}

.notification-icon.risk {

    color: #e11d48;

    background: #fff1f2;
}

.notification-icon.opportunity {

    color: #7c3aed;

    background: #f5f3ff;
}

.notification-icon.interview {

    color: #2563eb;

    background: #eff6ff;
}

.notification-content {

    min-width: 0;

    margin-left: 10px;

    padding-right: 22px;
}

.notification-content strong {

    display: block;

    color: #20283a;

    font-size: 11px;
}

.notification-content p {

    margin: 4px 0;

    color: #68758a;

    font-size: 10px;

    line-height: 1.5;
}

.notification-content small {

    display: block;

    color: #9aa4b3;

    font-size: 9px;
}

.notification-content time {

    display: block;

    margin-top: 3px;

    color: #a5adba;

    font-size: 9px;
}

.notification-dismiss {

    position: absolute;

    top: 12px;

    right: 10px;

    border: 0;

    background: transparent;

    color: #a6afbd;

    font-size: 10px;
}

.notification-empty {

    padding: 45px 20px;

    display: flex;

    flex-direction: column;

    align-items: center;

    text-align: center;

    color: #8b96a7;
}

.notification-empty i {

    margin-bottom: 9px;

    color: #10b981;

    font-size: 26px;
}

.notification-empty strong {

    color: #344054;

    font-size: 12px;
}

.notification-empty span {

    margin-top: 3px;

    font-size: 10px;
}


/* =========================================================
   CONTENT

   IMPORTANT:
   No fixed width.
   No max-width.
   No margin:auto.
   ========================================================= */

.c360-content {

    width: 100% !important;

    max-width: none !important;

    min-width: 0 !important;

    margin: 0 !important;

    padding: 26px 30px 45px !important;

    background: var(--c360-background);
}


/* =========================================================
   HERO
   ========================================================= */

.c360-hero {

    min-height: 176px;

    padding: 27px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 25px;

    background: #ffffff;

    border:
        1px solid #e3e7ed;

    border-radius: 18px;

    box-shadow: var(--c360-shadow);
}

.c360-hero-content {

    min-width: 0;
}

.c360-command-tag {

    display: inline-flex;

    align-items: center;

    padding: 6px 11px;

    border:
        1px solid #e6dafa;

    border-radius: 30px;

    background:
        linear-gradient(
            90deg,
            #faf5ff,
            #f5f3ff
        );

    color: #6d28d9;

    font-size: 10px;

    font-weight: 800;
}

.c360-command-tag i {

    margin-right: 7px;
}

.c360-hero h1 {

    margin: 12px 0 5px;

    color: #141927;

    font-size: 27px;

    line-height: 1.2;

    font-weight: 800;

    letter-spacing: -0.7px;
}

.c360-hero h1 span {

    font-size: 23px;
}

.c360-hero p {

    max-width: 630px;

    margin: 0;

    color: #6e7b8f;

    font-size: 13px;

    line-height: 1.6;
}

.c360-hero-actions {

    display: flex;

    align-items: center;

    gap: 10px;

    flex-shrink: 0;
}

.c360-btn {

    height: 40px;

    padding: 0 15px;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 8px;

    border-radius: 11px;

    font-size: 11px;

    font-weight: 700;

    white-space: nowrap;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.c360-btn:hover {

    transform: translateY(-2px);

    text-decoration: none;
}

.purple-btn {

    border: 0;

    background:
        linear-gradient(
            135deg,
            #7c3aed,
            #8b5cf6
        );

    color: #ffffff;

    box-shadow:
        0 7px 17px rgba(124,58,237,0.23);
}

.green-btn {

    border: 0;

    background:
        linear-gradient(
            135deg,
            #059669,
            #10b981
        );

    color: #ffffff;

    box-shadow:
        0 7px 17px rgba(16,185,129,0.2);
}

.white-btn {

    border:
        1px solid #dfe4eb;

    background: #ffffff;

    color: #445167;
}


/* =========================================================
   KPI GRID
   ========================================================= */

.c360-kpi-grid {

    margin-top: 25px;

    display: grid;

    grid-template-columns:
        repeat(6, minmax(0, 1fr));

    gap: 14px;
}

.c360-kpi-card {

    min-width: 0;

    min-height: 179px;

    padding: 17px;

    border:
        1px solid transparent;

    border-radius: 17px;

    box-shadow:
        0 5px 20px rgba(26,31,54,0.035);

    cursor: pointer;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.c360-kpi-card:hover {

    transform: translateY(-4px);

    box-shadow: var(--c360-shadow-hover);
}

.blue-card {

    background: #f2f7ff;

    border-color: #d8e8ff;
}

.purple-card {

    background: #f7f3ff;

    border-color: #ebe1ff;
}

.red-card {

    background: #fff2f3;

    border-color: #ffdfe4;
}

.green-card {

    background: #effcf5;

    border-color: #d5f5e4;
}

.yellow-card {

    background: #fffbea;

    border-color: #f9edbf;
}

.slate-card {

    background: #f8fafc;

    border-color: #e3e8ef;
}

.c360-kpi-top {

    display: flex;

    align-items: center;

    justify-content: space-between;

    color: #253047;

    font-size: 11px;

    font-weight: 700;
}

.c360-kpi-icon {

    width: 27px;

    height: 27px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 8px;

    font-size: 12px;
}

.blue-card .c360-kpi-icon {

    color: #2563eb;

    background: #dceaff;
}

.purple-card .c360-kpi-icon {

    color: #7c3aed;

    background: #ede4ff;
}

.red-card .c360-kpi-icon {

    color: #e11d48;

    background: #ffe0e5;
}

.green-card .c360-kpi-icon {

    color: #059669;

    background: #d8f7e8;
}

.yellow-card .c360-kpi-icon {

    color: #c98b00;

    background: #ffefb8;
}

.slate-card .c360-kpi-icon {

    color: #475569;

    background: #e7ecf2;
}

.c360-kpi-value {

    margin-top: 12px;

    color: #101828;

    font-size: 27px;

    line-height: 1;

    font-weight: 800;
}

.c360-kpi-value small {

    margin-left: 2px;

    color: #59657a;

    font-size: 13px;
}

.c360-kpi-footer {

    min-height: 40px;

    margin-top: 25px;

    padding-top: 11px;

    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    border-top:
        1px solid rgba(120,130,150,0.15);

    font-size: 9px;
}

.c360-kpi-footer span {

    max-width: 75px;

    color: #758197;
}

.c360-kpi-footer strong {

    color: #5b21b6;

    font-size: 10px;
}


/* =========================================================
   MAIN GRID
   ========================================================= */

.c360-main-grid {

    margin-top: 25px;

    display: grid;

    grid-template-columns:
        minmax(0, 2.1fr)
        minmax(300px, 1fr);

    gap: 22px;
}

.c360-panel {

    min-width: 0;

    background: #ffffff;

    border:
        1px solid #e2e7ed;

    border-radius: var(--c360-radius);

    box-shadow: var(--c360-shadow);
}


/* =========================================================
   PANEL HEADERS
   ========================================================= */

.c360-panel-header {

    padding: 21px 22px 0;

    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    gap: 15px;
}

.c360-section-label {

    display: block;

    color: #6d28d9;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 0.7px;
}

.c360-panel-header h2 {

    margin: 5px 0 0;

    color: #171c29;

    font-size: 16px;

    line-height: 1.25;

    font-weight: 800;
}

.c360-link-button {

    flex-shrink: 0;

    padding: 4px 0;

    border: 0;

    background: transparent;

    color: #6d28d9;

    font-size: 10px;

    font-weight: 800;
}

.c360-link-button i {

    margin-left: 4px;
}


/* =========================================================
   READINESS
   ========================================================= */

.readiness-panel {

    min-height: 388px;
}

.readiness-content {

    padding: 25px 26px;

    display: grid;

    grid-template-columns: 195px minmax(0,1fr);

    align-items: center;

    gap: 26px;
}

.readiness-score-card {

    min-height: 205px;

    padding: 18px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    border:
        1px solid #edf0f5;

    border-radius: 16px;

    background:
        linear-gradient(
            145deg,
            #fafbfe,
            #f6f8fb
        );
}

.readiness-circle {

    width: 120px;

    height: 120px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background:
        conic-gradient(
            #7c3aed 0deg,
            #7c3aed 259deg,
            #e9e3fb 259deg,
            #e9e3fb 360deg
        );
}

.readiness-circle-inner {

    width: 100px;

    height: 100px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #ffffff;
}

.readiness-circle-inner strong {

    color: #141b2a;

    font-size: 28px;

    line-height: 1;

    font-weight: 800;
}

.readiness-circle-inner span {

    margin-top: 3px;

    color: #8b95a6;

    font-size: 10px;
}

.readiness-title {

    margin-top: 12px;

    color: #263145;

    font-size: 11px;
}

.readiness-positive {

    margin-top: 7px;

    padding: 4px 8px;

    border:
        1px solid #bcefd8;

    border-radius: 20px;

    background: #ecfdf5;

    color: #059669;

    font-size: 9px;

    font-weight: 700;
}

.readiness-positive i {

    margin-right: 3px;
}

.readiness-bars {

    display: flex;

    flex-direction: column;

    gap: 19px;

    min-width: 0;
}

.readiness-row {

    position: relative;

    min-width: 0;
}

.readiness-row-title {

    display: flex;

    align-items: center;

    color: #344054;

    font-size: 11px;
}

.readiness-row-title strong {

    margin-left: auto;

    color: #667085;

    font-size: 10px;
}

.legend-dot {

    width: 9px;

    height: 9px;

    margin-right: 7px;

    flex-shrink: 0;

    border-radius: 50%;
}

.legend-dot.green {

    background: #10b981;
}

.legend-dot.blue {

    background: #3b82f6;
}

.legend-dot.red {

    background: #ef3f63;
}

.progress-track {

    width: 100%;

    height: 8px;

    margin-top: 7px;

    overflow: hidden;

    border-radius: 20px;

    background: #edf1f5;
}

.progress-fill {

    height: 100%;

    border-radius: 20px;

    transition: width 0.5s ease;
}

.green-fill {

    background: #10b981;
}

.blue-fill {

    background: #3b82f6;
}

.red-fill {

    background: #ef3f63;
}

.readiness-row small {

    position: absolute;

    right: 0;

    top: 1px;

    color: #9aa3b2;

    font-size: 9px;
}

.c360-panel-footer {

    margin: 0 26px;

    padding: 14px 0;

    display: flex;

    align-items: center;

    justify-content: space-between;

    border-top:
        1px solid #edf0f4;

    color: #9aa5b5;

    font-size: 9px;
}

.c360-panel-footer strong {

    color: #677489;
}


/* =========================================================
   RISK
   ========================================================= */

.risk-panel {

    min-height: 388px;
}

.ai-powered {

    padding: 5px 9px;

    border-radius: 7px;

    background: #f0eaff;

    color: #6d28d9;

    font-size: 8px;

    font-weight: 800;
}

.risk-total {

    padding: 21px 22px 13px;
}

.risk-total strong {

    display: block;

    color: #151c2b;

    font-size: 28px;

    line-height: 1;

    font-weight: 800;
}

.risk-total span {

    display: block;

    margin-top: 5px;

    color: #7d899a;

    font-size: 10px;
}

.risk-distribution {

    height: 8px;

    margin: 4px 22px 17px;

    display: flex;

    overflow: hidden;

    border-radius: 20px;

    background: #eef1f4;
}

.risk-segment {

    height: 100%;
}

.red-segment {

    background: #ef3f63;
}

.yellow-segment {

    background: #f5b91b;
}

.green-segment {

    background: #10b981;
}

.risk-list {

    padding: 0 22px;
}

.risk-item {

    min-height: 34px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    color: #334155;

    font-size: 10px;
}

.risk-item span {

    display: flex;

    align-items: center;

    min-width: 0;
}

.risk-item small {

    margin-left: 4px;

    color: #8894a5;

    font-size: 9px;
}

.risk-item strong {

    color: #263246;

    font-size: 11px;
}

.risk-dot {

    width: 9px;

    height: 9px;

    margin-right: 8px;

    flex-shrink: 0;

    border-radius: 50%;
}

.risk-dot.red {

    background: #ef3f63;
}

.risk-dot.yellow {

    background: #f5b91b;
}

.risk-dot.green {

    background: #10b981;
}

.risk-review-button {

    width: calc(100% - 44px);

    height: 40px;

    margin: 19px 22px 22px;

    border:
        1px solid #dfd2fa;

    border-radius: 12px;

    background: #faf7ff;

    color: #6d28d9;

    font-size: 10px;

    font-weight: 800;
}

.risk-review-button:hover {

    background: #f3eaff;
}


/* =========================================================
   THREE COLUMN SECTION
   ========================================================= */

.c360-three-grid {

    margin-top: 23px;

    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 22px;
}

.small-dashboard-card {

    min-width: 0;

    min-height: 320px;

    overflow: hidden;
}

.dashboard-list-item {

    margin: 16px 22px 0;

    padding: 12px;

    display: flex;

    align-items: center;

    min-width: 0;

    border:
        1px solid #edf0f4;

    border-radius: 13px;

    background: #fbfcfd;
}

.dashboard-item-icon {

    width: 34px;

    height: 34px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    font-size: 13px;
}

.red-icon {

    color: #e11d48;

    background: #ffe7eb;
}

.purple-icon {

    color: #7c3aed;

    background: #eee7ff;
}

.orange-icon {

    color: #ea580c;

    background: #fff0df;
}

.yellow-icon {

    color: #b77900;

    background: #fff3c7;
}

.green-icon {

    color: #059669;

    background: #ddf8eb;
}

.dashboard-item-text {

    min-width: 0;

    margin-left: 10px;

    flex: 1;
}

.dashboard-item-text strong {

    display: block;

    color: #273145;

    font-size: 10px;
}

.dashboard-item-text span {

    display: block;

    margin-top: 3px;

    color: #8b96a6;

    font-size: 9px;

    line-height: 1.35;
}

.dashboard-item-action {

    flex-shrink: 0;

    margin-left: 7px;

    border: 0;

    background: transparent;

    color: #6d28d9;

    font-size: 9px;

    font-weight: 800;
}

.status-badge {

    flex-shrink: 0;

    padding: 5px 8px;

    border-radius: 20px;

    font-size: 8px;

    font-weight: 800;
}

.status-badge.urgent {

    color: #e11d48;

    background: #ffe6eb;
}

.status-badge.watching {

    color: #a16207;

    background: #fff4cc;
}

.status-badge.completed {

    color: #047857;

    background: #dcf8eb;
}


/* =========================================================
   TRAINING
   ========================================================= */

.training-summary {

    margin: 17px 22px;

    display: grid;

    grid-template-columns: 1fr 1fr;

    border:
        1px solid #edf0f4;

    border-radius: 14px;

    background: #fbfcfd;
}

.training-stat {

    padding: 16px;

    border-right:
        1px solid #edf0f4;
}

.training-stat:last-child {

    border-right: 0;
}

.training-stat span {

    display: block;

    color: #7b8798;

    font-size: 8px;

    font-weight: 800;
}

.training-stat strong {

    display: block;

    margin-top: 8px;

    color: #6d28d9;

    font-size: 19px;

    font-weight: 800;
}

.training-stat small {

    display: block;

    margin-top: 2px;

    color: #9aa4b2;

    font-size: 8px;
}

.training-highlight {

    margin: 0 22px 20px;

    padding: 13px;

    display: flex;

    align-items: center;

    border:
        1px solid #e7defb;

    border-radius: 13px;

    background:
        linear-gradient(
            135deg,
            #fbf8ff,
            #f8f5ff
        );
}

.training-highlight-icon {

    width: 35px;

    height: 35px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    background: #eee6ff;

    color: #7c3aed;

    font-size: 14px;
}

.training-highlight > div:nth-child(2) {

    min-width: 0;

    flex: 1;

    margin-left: 10px;
}

.training-highlight strong {

    display: block;

    color: #283246;

    font-size: 10px;
}

.training-highlight span {

    display: block;

    margin-top: 3px;

    color: #8994a5;

    font-size: 8px;
}

.training-highlight button {

    flex-shrink: 0;

    border: 0;

    background: transparent;

    color: #6d28d9;

    font-size: 9px;

    font-weight: 800;
}


/* =========================================================
   APPLICATION + RECRUITMENT
   ========================================================= */

.c360-bottom-grid {

    margin-top: 23px;

    display: grid;

    grid-template-columns:
        1.25fr
        1fr;

    gap: 22px;
}

.application-panel,
.recruitment-panel {

    min-height: 265px;
}

.application-main-number {

    padding: 25px 22px 16px;

    display: flex;

    align-items: center;

    gap: 14px;
}

.application-main-number strong {

    color: #6d28d9;

    font-size: 34px;

    line-height: 1;

    font-weight: 800;
}

.application-main-number span {

    max-width: 210px;

    color: #7a8798;

    font-size: 10px;
}

.application-info-grid {

    padding: 0 22px;

    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 12px;
}

.application-info-box {

    padding: 13px;

    display: flex;

    align-items: flex-start;

    border:
        1px solid #edf0f4;

    border-radius: 12px;

    background: #fbfcfd;
}

.application-info-box > i {

    width: 31px;

    height: 31px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 9px;

    background: #f0eaff;

    color: #7c3aed;

    font-size: 12px;
}

.application-info-box div {

    min-width: 0;

    margin-left: 9px;
}

.application-info-box strong {

    display: block;

    color: #2b3547;

    font-size: 9px;
}

.application-info-box span {

    display: block;

    margin-top: 3px;

    color: #909aaa;

    font-size: 8px;

    line-height: 1.4;
}

.application-open-button {

    margin: 17px 22px 21px;

    padding: 9px 13px;

    border:
        1px solid #ddd1fb;

    border-radius: 10px;

    background: #faf7ff;

    color: #6d28d9;

    font-size: 9px;

    font-weight: 800;
}


/* =========================================================
   RECRUITMENT
   ========================================================= */

.recruitment-stat-grid {

    padding: 22px;

    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 12px;
}

.recruitment-stat {

    min-height: 83px;

    padding: 13px;

    border-radius: 13px;

    border:
        1px solid transparent;
}

.purple-stat {

    background: #f6f1ff;

    border-color: #eadfff;
}

.yellow-stat {

    background: #fffbea;

    border-color: #f8edc7;
}

.orange-stat {

    background: #fff5ec;

    border-color: #ffe6cc;
}

.green-stat {

    background: #effcf5;

    border-color: #d7f5e5;
}

.recruitment-stat-icon {

    width: 25px;

    height: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 7px;

    font-size: 11px;
}

.purple-stat .recruitment-stat-icon {

    color: #7c3aed;

    background: #e9dcff;
}

.yellow-stat .recruitment-stat-icon {

    color: #b77900;

    background: #ffedb2;
}

.orange-stat .recruitment-stat-icon {

    color: #ea580c;

    background: #ffe4ca;
}

.green-stat .recruitment-stat-icon {

    color: #059669;

    background: #d5f6e5;
}

.recruitment-stat span {

    display: block;

    margin-top: 7px;

    color: #7c8797;

    font-size: 8px;

    font-weight: 700;
}

.recruitment-stat strong {

    display: block;

    margin-top: 2px;

    color: #202a3b;

    font-size: 20px;

    line-height: 1;

    font-weight: 800;
}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.c360-quick-actions-panel {

    margin-top: 23px;

    padding: 22px;

    background: #ffffff;

    border:
        1px solid #e2e7ed;

    border-radius: var(--c360-radius);

    box-shadow: var(--c360-shadow);
}

.quick-actions-heading {

    display: flex;

    align-items: center;

    justify-content: space-between;
}

.quick-actions-heading h2 {

    margin: 4px 0 0;

    color: #171c29;

    font-size: 16px;

    font-weight: 800;
}

.quick-actions-live {

    display: inline-flex;

    align-items: center;

    color: #059669;

    font-size: 9px;

    font-weight: 700;
}

.quick-actions-live i {

    margin-right: 5px;

    font-size: 7px;
}

.quick-actions-grid {

    margin-top: 16px;

    display: grid;

    grid-template-columns:
        repeat(3, minmax(0,1fr));

    gap: 11px;
}

.quick-action {

    min-width: 0;

    min-height: 82px;

    padding: 12px;

    display: flex;

    align-items: center;

    text-align: left;

    border-radius: 13px;

    text-decoration: none;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.quick-action:hover {

    transform: translateY(-3px);

    box-shadow:
        0 8px 22px rgba(20,25,45,0.09);

    text-decoration: none;
}

.purple-action {

    background: #f7f2ff;

    border:
        1px solid #e8dcff;
}

.blue-action {

    background: #f1f7ff;

    border:
        1px solid #dbeaff;
}

.red-action {

    background: #fff2f4;

    border:
        1px solid #ffe0e6;
}

.orange-action {

    background: #fff6ee;

    border:
        1px solid #ffe5d1;
}

.green-action {

    background: #effcf6;

    border:
        1px solid #d9f5e6;
}

.violet-action {

    background: #f5f3ff;

    border:
        1px solid #e7e1ff;
}

.quick-action-icon {

    width: 35px;

    height: 35px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    font-size: 13px;
}

.purple-action .quick-action-icon {

    color: #7c3aed;

    background: #eadfff;
}

.blue-action .quick-action-icon {

    color: #2563eb;

    background: #dceaff;
}

.red-action .quick-action-icon {

    color: #e11d48;

    background: #ffe0e6;
}

.orange-action .quick-action-icon {

    color: #ea580c;

    background: #ffe3cd;
}

.green-action .quick-action-icon {

    color: #059669;

    background: #d7f5e6;
}

.violet-action .quick-action-icon {

    color: #7c3aed;

    background: #e9e2ff;
}

.quick-action-content {

    min-width: 0;

    flex: 1;

    margin-left: 10px;
}

.quick-action-content strong {

    display: block;

    color: #293347;

    font-size: 10px;
}

.quick-action-content small {

    display: block;

    margin-top: 4px;

    color: #8b96a7;

    font-size: 8px;

    line-height: 1.35;
}

.quick-action-arrow {

    flex-shrink: 0;

    margin-left: 7px;

    color: #8a94a4;

    font-size: 10px;
}


/* =========================================================
   AI CARD
   ========================================================= */

.c360-ai-card {

    margin-top: 23px;

    padding: 22px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 25px;

    border-radius: 18px;

    background:
        linear-gradient(
            135deg,
            #211343,
            #34176a 52%,
            #4c1d95
        );

    color: #ffffff;

    box-shadow:
        0 12px 32px rgba(76,29,149,0.18);
}

.c360-ai-content {

    display: flex;

    align-items: center;

    min-width: 0;
}

.c360-ai-icon {

    width: 48px;

    height: 48px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 14px;

    background:
        rgba(255,255,255,0.12);

    color: #ddd6fe;

    font-size: 20px;
}

.c360-ai-content > div:last-child {

    margin-left: 14px;

    min-width: 0;
}

.c360-ai-card .c360-section-label {

    color: #c4b5fd;
}

.c360-ai-card h2 {

    margin: 4px 0;

    color: #ffffff;

    font-size: 18px;
}

.c360-ai-card p {

    max-width: 560px;

    margin: 0;

    color: #c8c1da;

    font-size: 10px;
}

.c360-ai-actions {

    display: flex;

    flex-wrap: wrap;

    justify-content: flex-end;

    gap: 7px;
}

.c360-ai-actions button {

    height: 34px;

    padding: 0 11px;

    border:
        1px solid rgba(255,255,255,0.13);

    border-radius: 9px;

    background:
        rgba(255,255,255,0.08);

    color: #f4f1fb;

    font-size: 9px;

    font-weight: 700;
}

.c360-ai-actions .ai-primary {

    border: 0;

    background: #ffffff;

    color: #5b21b6;
}


/* =========================================================
   COLLAPSED SIDEBAR
   ========================================================= */

.c360-app.sidebar-collapsed .c360-sidebar {

    width: 76px;
}

.c360-app.sidebar-collapsed .c360-main {

    left: 76px;
}

.c360-app.sidebar-collapsed .c360-brand {

    justify-content: center;

    padding: 18px 10px;
}

.c360-app.sidebar-collapsed .c360-brand-text,
.c360-app.sidebar-collapsed .c360-tpo-info,
.c360-app.sidebar-collapsed .c360-nav-title,
.c360-app.sidebar-collapsed .c360-nav-item span,
.c360-app.sidebar-collapsed .c360-sidebar-footer {

    display: none;
}

.c360-app.sidebar-collapsed .c360-tpo-profile {

    justify-content: center;

    padding: 10px;
}

.c360-app.sidebar-collapsed .c360-nav-item {

    justify-content: center;

    padding: 0;
}

.c360-app.sidebar-collapsed .c360-nav-item i {

    margin-right: 0;
}


/* =========================================================
   LARGE SCREEN
   ========================================================= */

@media (min-width: 1500px) {

    .c360-content {

        padding-left: 36px !important;

        padding-right: 36px !important;
    }

    .c360-kpi-grid {

        gap: 17px;
    }

    .c360-main-grid,
    .c360-three-grid,
    .c360-bottom-grid {

        gap: 24px;
    }
}


/* =========================================================
   MEDIUM DESKTOP
   ========================================================= */

@media (max-width: 1250px) {

    .c360-kpi-grid {

        grid-template-columns:
            repeat(3, minmax(0,1fr));
    }

    .c360-main-grid {

        grid-template-columns: 1fr;
    }

    .c360-three-grid {

        grid-template-columns:
            repeat(2, minmax(0,1fr));
    }

    .c360-bottom-grid {

        grid-template-columns: 1fr;
    }

    .quick-actions-grid {

        grid-template-columns:
            repeat(2, minmax(0,1fr));
    }

    .c360-search {

        width: min(32vw, 380px);
    }
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 950px) {

    .c360-sidebar {

        width: 235px;
    }

    .c360-main {

        left: 235px;
    }

    .c360-content {

        padding: 20px !important;
    }

    .c360-hero {

        align-items: flex-start;

        flex-direction: column;
    }

    .c360-hero-actions {

        width: 100%;
    }

    .c360-search {

        display: none;
    }

    .c360-three-grid {

        grid-template-columns: 1fr;
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

    .c360-sidebar {

        width: 0;

        transform: translateX(-100%);
    }

    .c360-main {

        left: 0;
    }

    .c360-content {

        padding: 14px !important;
    }

    .c360-topbar {

        padding: 0 14px;
    }

    .c360-breadcrumb {

        font-size: 11px;
    }

    .c360-user-details {

        display: none;
    }

    .c360-top-divider {

        display: none;
    }

    .c360-kpi-grid {

        grid-template-columns:
            repeat(2, minmax(0,1fr));
    }

    .readiness-content {

        grid-template-columns: 1fr;
    }

    .readiness-score-card {

        min-height: 180px;
    }

    .c360-hero-actions {

        flex-wrap: wrap;
    }

    .c360-btn {

        flex: 1;

        min-width: 130px;
    }

    .quick-actions-grid {

        grid-template-columns: 1fr;
    }

    .c360-ai-card {

        align-items: flex-start;

        flex-direction: column;
    }

    .c360-ai-actions {

        width: 100%;

        justify-content: flex-start;
    }

    .c360-notification-popover {

        position: fixed;

        top: 65px;

        left: 10px;

        right: 10px;

        width: auto;
    }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {

    .c360-kpi-grid {

        grid-template-columns: 1fr;
    }

    .c360-hero {

        padding: 20px;
    }

    .c360-hero h1 {

        font-size: 23px;
    }

    .application-info-grid {

        grid-template-columns: 1fr;
    }

    .recruitment-stat-grid {

        grid-template-columns: 1fr;
    }

    .c360-panel-header {

        padding-left: 17px;

        padding-right: 17px;
    }

    .dashboard-list-item {

        margin-left: 17px;

        margin-right: 17px;
    }
}

sp_widget.script:
(function() {

    /* =========================================================
       CAMPUS360 TPO DASHBOARD CENTER - SERVER SCRIPT
       ========================================================= */

    data.tpo = {
        id: 'TPO001',
        name: 'Ananya Rao',
        firstName: 'Ananya',
        initials: 'AR',
        email: 'ananya.rao@cmrit.ac.in',
        phone: '+91 9876543210',
        college: 'CMR Institute of Technology',
        department: 'Training & Placement Office',
        designation: 'Training & Placement Officer'
    };

    data.counts = {
        students: 0,
        companies: 0,
        opportunities: 0,
        applications: 0,
        placed: 0
    };

    data.readiness = {
        average: 72,
        high: 0,
        medium: 0,
        low: 0,
        highPercent: 0,
        mediumPercent: 0,
        lowPercent: 0
    };

    data.risk = {
        total: 0,
        high: 0,
        medium: 0,
        low: 0,
        highPercent: 0,
        mediumPercent: 0,
        lowPercent: 0
    };

    data.notifications = [];
    data.unreadCount = 0;
    data.aiWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5');

    function getCount(tableName, encodedQuery) {
        var ga = new GlideAggregate(tableName);
        if (encodedQuery) ga.addEncodedQuery(encodedQuery);
        ga.addAggregate('COUNT');
        ga.query();
        if (ga.next()) return parseInt(ga.getAggregate('COUNT'), 10) || 0;
        return 0;
    }

    // Counts
    data.counts.students = getCount('x_snc_campus360_student_master');
    data.counts.companies = getCount('x_snc_campus360_company_master');
    data.counts.opportunities = getCount('x_snc_campus360_placement_opportunity');
    data.counts.applications = getCount('x_snc_campus360_student_application');

    // Risk counts
    data.risk.high = getCount('x_snc_campus360_placement_intelligence', 'risk_level=High^ORreadiness_score<60');
    data.risk.medium = getCount('x_snc_campus360_placement_intelligence', 'risk_level=Medium^ORreadiness_scoreBETWEEN60@79');
    data.risk.low = getCount('x_snc_campus360_placement_intelligence', 'risk_level=Low^ORreadiness_score>=80');
    data.risk.total = data.risk.high + data.risk.medium + data.risk.low;

    if (data.risk.total > 0) {
        data.risk.highPercent = Math.round((data.risk.high / data.risk.total) * 100);
        data.risk.mediumPercent = Math.round((data.risk.medium / data.risk.total) * 100);
        data.risk.lowPercent = Math.round((data.risk.low / data.risk.total) * 100);
    }

    /* =========================================================
       REAL TPO NOTIFICATION ENGINE
       1. At-Risk Students Summary Alert
       2. Newly Published Opportunities by Recruiters
       3. Scheduled Student Interviews by Recruiters
       ========================================================= */

    // 1. At-Risk Students Alert
    if (data.risk.high > 0) {
        data.notifications.push({
            sys_id: 'tpo_notif_risk_summary',
            type: 'risk',
            title: 'At-Risk Students Alert',
            message: data.risk.high + ' students have been flagged as High Placement Risk due to low skill readiness (<60%) or low attendance.',
            meta: data.risk.high + ' High-Risk Students',
            time: 'Active Alert'
        });
    }

    // 2. Newly Published Opportunities
    var oppGR = new GlideRecord('x_snc_campus360_placement_opportunity');
    oppGR.orderByDesc('sys_created_on');
    oppGR.setLimit(5);
    oppGR.query();

    while (oppGR.next()) {
        var companyName = oppGR.getDisplayValue('company') || 'Partner Recruiter';
        var jobRole = oppGR.getValue('job_role') || oppGR.getValue('title') || 'Placement Drive';
        var ctc = oppGR.getValue('ctc_package') || oppGR.getValue('ctc') || 'As per norms';
        var deadline = oppGR.getDisplayValue('deadline') || 'Open';
        var createdOn = oppGR.getDisplayValue('sys_created_on') || 'Recently';

        data.notifications.push({
            sys_id: 'tpo_notif_opp_' + oppGR.getUniqueValue(),
            type: 'opportunity',
            title: 'New Opportunity Published: ' + jobRole,
            message: companyName + ' has published a new placement opportunity for ' + jobRole + ' (Package: ' + ctc + '). Application Deadline: ' + deadline,
            meta: 'Company: ' + companyName + ' | CTC: ' + ctc,
            time: createdOn
        });
    }

    // 3. Recruiter Scheduled Interviews for Students
    var intGR = new GlideRecord('x_snc_campus360_recruiter_interview');
    if (intGR.isValid()) {
        intGR.orderByDesc('sys_created_on');
        intGR.setLimit(5);
        intGR.query();

        while (intGR.next()) {
            var studentName = intGR.getDisplayValue('student') || 'Candidate Student';
            var compName = intGR.getDisplayValue('company') || 'Recruiter';
            var intDate = intGR.getDisplayValue('interview_date') || intGR.getDisplayValue('scheduled_time') || 'Upcoming';
            var round = intGR.getValue('interview_round') || intGR.getValue('round') || 'Technical Round';

            data.notifications.push({
                sys_id: 'tpo_notif_int_' + intGR.getUniqueValue(),
                type: 'interview',
                title: 'Recruiter Interview Scheduled',
                message: 'Interview scheduled for ' + studentName + ' with ' + compName + ' (' + round + ') on ' + intDate + '.',
                meta: 'Student: ' + studentName + ' | Round: ' + round,
                time: intDate
            });
        }
    }

    // Fallback Mock Interviews if recruiter interview table is light
    if (data.notifications.filter(function(n){ return n.type === 'interview'; }).length === 0) {
        var mockGR = new GlideRecord('x_snc_campus360_mock_interview');
        mockGR.orderByDesc('sys_created_on');
        mockGR.setLimit(4);
        mockGR.query();

        while (mockGR.next()) {
            var sName = mockGR.getDisplayValue('student') || 'Student Candidate';
            var tName = mockGR.getDisplayValue('trainer') || 'Trainer';
            var mDate = mockGR.getDisplayValue('scheduled_date') || mockGR.getDisplayValue('sys_created_on') || 'Scheduled';

            data.notifications.push({
                sys_id: 'tpo_notif_mock_' + mockGR.getUniqueValue(),
                type: 'interview',
                title: 'Student Interview Scheduled',
                message: 'Mock / Technical Interview scheduled for student ' + sName + ' with Trainer ' + tName + '.',
                meta: 'Student: ' + sName + ' | Trainer: ' + tName,
                time: mDate
            });
        }
    }

    data.unreadCount = data.notifications.length;

})();
(function() {
    var tpoGR = new GlideRecord('x_snc_campus360_campus360_tpo_profile');
    tpoGR.query();
    if (tpoGR.next()) {
        data.tpoName = tpoGR.getValue('tpo_name') || 'MD Ali';
        data.tpoInitials = 'MA';
        data.tpoTitle = tpoGR.getValue('designation') || 'Training & Placement Officer';
        data.tpoOffice = tpoGR.getValue('college_name') || 'CMR Institute of Technology';
    } else {
        data.tpoName = 'MD Ali';
        data.tpoInitials = 'MA';
        data.tpoTitle = 'TPO';
        data.tpoOffice = 'Training & Placement Office';
    }
})();
